    {
      "hunk_id": "H067",
      "decision": "SOL",
      "reason": "“Lived and died a good fisherman” preserves the contrast with Sudal’s adventurous ambition."
    },
    {
      "hunk_id": "H068",
      "decision": "SOL",
      "reason": "His success as a river pirate is retained in H069."
    },
    {
      "hunk_id": "H069",
      "decision": "SOL",
      "reason": "SOL keeps his recent doubts while preserving that he had done well as a pirate."
    },
    {
      "hunk_id": "H070",
      "decision": "SOL",
      "reason": "“Nothing” retains the point that he was doing no meaningful work."
    },
    {
      "hunk_id": "H071",
      "decision": "SOL",
      "reason": "The routine and inactivity are retained in the recast passage."
    },
    {
      "hunk_id": "H072",
      "decision": "SOL",
      "reason": "“That was all” is retained at the end of H071."
    },
    {
      "hunk_id": "H073",
      "decision": "SOL",
      "reason": "The journey down the tributaries and their wasted time remain clear."
    },
    {
