    {
      "hunk_id": "H079",
      "decision": "SOL",
      "reason": "The empty-words observation is retained in H078."
    },
    {
      "hunk_id": "H080",
      "decision": "SOL",
      "reason": "Removing “merely” does not alter the warm smile or the answer."
    },
    {
      "hunk_id": "H081",
      "decision": "SOL",
      "reason": "“Nearby” and the request for another favor preserve the sense of the exchange."
    },
    {
      "hunk_id": "H082",
      "decision": "SOL",
      "reason": "“A living to make” is idiomatic and preserves the livelihood objection."
    },
    {
      "hunk_id": "H083",
      "decision": "SOL",
      "reason": "The living/alive wordplay remains intact in natural dialogue."
    },
    {
      "hunk_id": "H084",
      "decision": "SOL",
      "reason": "The shortened ellipsis preserves the shocked pause."
    },
    {
      "hunk_id": "H085",
      "decision": "SOL",
      "reason": "The line still states plainly that the favor was a threat."
    },
    {
      "hunk_id": "H086",
      "decision": "SOL",
      "reason": "The recast phrasing preserves the rule that the stronger martial artist is king."
    },
    {
      "hunk_id": "H087",
      "decision": "SOL",
      "reason": "“Really was called a king” keeps the contrast between the title and the literal king."
    },
    {
      "hunk_id": "H088",
      "decision": "SOL",
      "reason": "SOL retains the prolonged wait, the tributary, and the lack of other boats."
    },
    {
      "hunk_id": "H089",
      "decision": "SOL",
      "reason": "The transition still marks that the situation lasted until yesterday’s idea."
    },
    {
      "hunk_id": "H090",
      "decision": "SOL",
      "reason": "The thought keeps both his frustration and the time before Jin Taekyung returns."
    },
    {
      "hunk_id": "H091",
      "decision": "SOL",
      "reason": "The recast keeps his Yangtze experience and his opinion of Nanman."
    },
    {
      "hunk_id": "H092",
      "decision": "SOL",
      "reason": "SOL preserves that the mission cannot be simple, in natural phrasing."
    },
    {
      "hunk_id": "H093",
      "decision": "BASE",
      "reason": "SOL drops the source’s comic image of whining like a dog that needs to shit."
    },
    {
      "hunk_id": "H094",
      "decision": "SOL",
      "reason": "The subject remains clear from context, and the order to his men follows."
    },
    {
      "hunk_id": "H095",
      "decision": "SOL",
      "reason": "“Right next door” already conveys the short distance."
    },
    {
      "hunk_id": "H096",
      "decision": "SOL",
      "reason": "The plan’s poor reception remains clear from the following objections."
    },
    {
      "hunk_id": "H097",
      "decision": "SOL",
      "reason": "“Stronghold Lord” preserves the distinction between the deputy and the actual leader."
    },
    {
      "hunk_id": "H098",
      "decision": "SOL",
      "reason": "The plan is still his response to his men’s objections."
    },
    {
      "hunk_id": "H099",
      "decision": "SOL",
      "reason": "The broken repetition keeps Sudal searching for the name of Taekyung’s tactic."
    },
    {
      "hunk_id": "H100",
      "decision": "BASE",
      "reason": "SOL’s “had gone into the water” can imply voluntary entry; BASE preserves that Sudal dunked them."
    },
    {
      "hunk_id": "H101",
      "decision": "BASE",
      "reason": "SOL adds “first,” an ordinal absent from the source’s target-after-a-long-time phrasing."
    },
    {
      "hunk_id": "H102",
      "decision": "BASE",
      "reason": "“Just like now” supplies the source’s present-moment transition."
    },
    {
      "hunk_id": "H103",
      "decision": "SOL",
      "reason": "The last-raid question is retained at the start of H104."
    },
    {
      "hunk_id": "H104",
      "decision": "SOL",
      "reason": "The merged passage retains the question and Sudal’s pose at the stern."
    },
    {
      "hunk_id": "H105",
      "decision": "SOL",
      "reason": "The shorter phrasing preserves that he noticed the problem before fifteen minutes passed."
    },
    {
      "hunk_id": "H106",
      "decision": "SOL",
      "reason": "“Almost upon them” keeps the ship’s close approach and the lack of crew or captain."
    },
    {
      "hunk_id": "H107",
      "decision": "SOL",
      "reason": "“Waited for them” preserves the lone person’s deliberate presence."
    },
    {
      "hunk_id": "H108",
      "decision": "SOL",
      "reason": "“What fortunate timing” naturally conveys that the ship’s arrival is convenient."
    },
    {
      "hunk_id": "H109",
      "decision": "SOL",
      "reason": "The shorter ellipsis preserves the frozen reaction."
    }
  ]
}

